def build_cipher(self, iv=None, alg='aes_128_cbc'):
        """
        :param iv: init vector
        :param alg: cipher algorithm
        :return: A Cipher instance
        """
        typ, bits, cmode = alg.lower().split('_')
        bits = int(bits)

        if not iv:
            if self.iv:
                iv = self.iv
            else:
                iv = os.urandom(AES_BLOCK_SIZE)

        if len(iv) != AES_BLOCK_SIZE:
            raise Exception('Wrong iv size: {}'.format(len(iv)))

        if bits not in algorithms.AES.key_sizes:
            raise Exception('Unsupported key length: {}'.format(bits))

        if len(self.key) != bits / 8:
            raise Exception('Wrong Key length: {}'.format(len(self.key)))

        try:
            mode = POSTFIX_MODE[cmode]
        except KeyError:
            raise Exception('Unsupported chaining mode: {}'.format(cmode))

        cipher = Cipher(
                algorithms.AES(self.key),
                mode(iv),
                backend=default_backend())

        return cipher, iv

def brotli_generator(input_stream, chunk_size=DEFAULT_CHUNK_SIZE):
    decompressor = brotli.Decompressor()

    while True:
        compressed_chunk = input_stream.read(chunk_size)
        if not compressed_chunk:
            break

        yield decompressor.process(compressed_chunk)

    assert_(decompressor.is_finished())

def brotli_generator(input_stream, chunk_size=DEFAULT_CHUNK_SIZE):
    # implementation notes: in principle chunk_size for input and output could be different, we keep them the same here.
    # I've also seen that the actual output data may be quite a bit larger than the output_buffer_limit; a detail that
    # I do not fully understand (but I understand that at least it's not _unboundedly_ larger).

    decompressor = brotli.Decompressor()
    input_is_finished = False

    while not (decompressor.is_finished() and input_is_finished):
        if decompressor.can_accept_more_data():
            compressed_chunk = input_stream.read(chunk_size)
            if not compressed_chunk:
                input_is_finished = True
                data = decompressor.process(b"", output_buffer_limit=chunk_size)  # b"": no input available, "drain"
            else:
                data = decompressor.process(compressed_chunk, output_buffer_limit=chunk_size)
        else:
            data = decompressor.process(b"", output_buffer_limit=chunk_size)  # b"" compressor cannot accept more input

        if data:
            yield data

def verify_math_expression(
    expression: str,
    claimed_result: str,
    operation: str = "evaluate"
) -> dict:
    """
    Verify a mathematical expression using SymPy.

    Args:
        expression: The mathematical expression (e.g., "x^2")
        claimed_result: The claimed result (e.g., "2x" for derivative)
        operation: One of "derivative", "integral", "simplify", "solve", "evaluate"

    Returns:
        Verification result with verified status and details
    """
    try:
        from sympy import (
            symbols, sympify, diff, integrate, simplify, solve,
            Eq, parse_expr, sqrt, sin, cos, exp, log, pi, E
        )
        from sympy.parsing.sympy_parser import (
            parse_expr, standard_transformations, 
            implicit_multiplication_application, convert_xor
        )

        # Common symbol
        x, y, z = symbols('x y z')

        # Transformation for parsing
        transformations = standard_transformations + (
            implicit_multiplication_application,
            convert_xor,
        )

        # Parse expression
        try:
            expr = parse_expr(
                expression.replace("^", "**"),
                local_dict={"x": x, "y": y, "z": z, "pi": pi, "e": E},
                transformations=transformations
            )
        except Exception as e:
            return {
                "verified": False,
                "message": f"Could not parse expression: {expression}",
                "error": str(e)
            }

        # Parse claimed result
        try:
            claimed = parse_expr(
                claimed_result.replace("^", "**"),
                local_dict={"x": x, "y": y, "z": z, "pi": pi, "e": E},
                transformations=transformations
            )
        except Exception as e:
            return {
                "verified": False,
                "message": f"Could not parse claimed result: {claimed_result}",
                "error": str(e)
            }

        # Perform operation
        if operation == "derivative":
            actual = diff(expr, x)
        elif operation == "integral":
            actual = integrate(expr, x)
        elif operation == "simplify":
            actual = simplify(expr)
        elif operation == "solve":
            actual = solve(expr, x)
        else:  # evaluate
            actual = simplify(expr)

        # Compare results
        if operation == "solve":
            # For solve, check if solutions match
            verified = set(actual) == set([claimed]) if not isinstance(claimed, list) else set(actual) == set(claimed)
        else:
            # For other operations, simplify and compare
            difference = simplify(actual - claimed)
            verified = difference == 0

        return {
            "verified": verified,
            "message": "Calculation verified" if verified else "Calculation incorrect",
            "expected": str(actual),
            "actual": str(claimed),
            "operation": operation
        }

    except ImportError:
        return {
            "verified": False,
            "message": "SymPy not installed. Install with: pip install sympy",
            "error": "ImportError"
        }
    except Exception as e:
        logger.error(f"Math verification failed: {e}")
        return {
            "verified": False,
            "message": f"Verification error: {str(e)}",
            "error": str(e)
        }

