def safer_getattr(object, name, default=None, getattr=getattr):
    """Getattr implementation which prevents using format on string objects.

    format() is considered harmful:
    http://lucumr.pocoo.org/2016/12/29/careful-with-str-format/

    """
    if type(name) is not str:
        raise TypeError('type(name) must be str')
    if name in ('format', 'format_map') and (
            isinstance(object, str) or
            (isinstance(object, type) and issubclass(object, str))):
        raise NotImplementedError(
            'Using the format*() methods of `str` is not safe')
    if name in INSPECT_ATTRIBUTES:
        raise AttributeError(
            f'"{name}" is a restricted name,'
            ' that is forbidden to access in RestrictedPython.')
    if name.startswith('_'):
        raise AttributeError(
            '"{name}" is an invalid attribute name because it '
            'starts with "_"'.format(name=name)
        )
    args = (object, name) + (() if default is raise_ else (default,))
    return getattr(*args)

def isInList(self, lst, type_, value):
        """
        Checks if a specific value is in a list

        :param arg1: Options: "whitelist" or "blacklist"
        :type arg1: string
        :param arg2: Options: "ip", "port", "domain", or "scheme"
        :type arg2: string
        :param arg3: Value to check for
        :type arg3: string

        :rtype: bool
        """
        _check_allowed_lists(lst)
        _check_allowed_keys(type_)

        dst = self._lists[lst][type_]

        if len(dst) == 0:
            if lst == "whitelist":
                return True
            else:
                return False

        if type_ == "domain":
            for domain in dst:
                if domain.lower() == value.lower():
                    return True
            return False
        else:
            return value in dst

