def extract_field_values(cls, formatted_string: str) -> Optional[Dict[str, Any]]:
        """
        Extracts field values from an XML-formatted string.

        Args:
            formatted_string (str): The XML-formatted string to parse.

        Returns:
            Optional[Dict[str, Any]]: A dictionary containing the extracted field
                values, where keys are the XML element names and values are their
                corresponding contents.
            Returns None if parsing fails or the root element is not a dictionary.

        Raises:
            etree.XMLSyntaxError: If the input string is not valid XML.
        """
        parser = etree.XMLParser(strip_cdata=False)
        root = etree.fromstring(formatted_string.encode("utf-8"), parser=parser)

        def parse_element(element: etree._Element) -> Any:
            # Skip elements starting with underscore
            if element.tag.startswith("_"):
                return {}

            field_info = cls.__fields__.get(element.tag)
            is_verbatim = field_info and field_info.field_info.extra.get(
                "verbatim", False
            )

            if is_verbatim:
                # For code elements, preserve the content as is, including whitespace
                content = element.text if element.text else ""
                # Strip leading and trailing triple backticks if present,
                # accounting for whitespace
                return (
                    content.strip().removeprefix("```").removesuffix("```").strip()
                    if content.strip().startswith("```")
                    and content.strip().endswith("```")
                    else content
                )
            elif len(element) == 0:
                # For non-code leaf elements, strip whitespace
                return element.text.strip() if element.text else ""
            else:
                # For branch elements, handle potential lists or nested structures
                children = [parse_element(child) for child in element]
                if all(child.tag == element[0].tag for child in element):
                    # If all children have the same tag, treat as a list
                    return children
                else:
                    # Otherwise, treat as a dictionary
                    result = {child.tag: parse_element(child) for child in element}
                    # Check if this corresponds to a nested Pydantic model
                    if field_info and issubclass(field_info.type_, BaseModel):
                        return field_info.type_(**result)
                    return result

        result = parse_element(root)
        if not isinstance(result, dict):
            return None
        # Filter out empty dictionaries from skipped underscore fields
        return {k: v for k, v in result.items() if v != {}}

def extract_field_values(cls, formatted_string: str) -> Optional[Dict[str, Any]]:
        """
        Extracts field values from an XML-formatted string.

        Args:
            formatted_string (str): The XML-formatted string to parse.

        Returns:
            Optional[Dict[str, Any]]: A dictionary containing the extracted field
                values, where keys are the XML element names and values are their
                corresponding contents.
            Returns None if parsing fails or the root element is not a dictionary.

        Raises:
            etree.XMLSyntaxError: If the input string is not valid XML.
        """
        # SECURITY: Initialize XMLParser with flags to prevent 
        # XML External Entity (XXE), billion laughs, and external DTD attacks by 
        # disabling entity resolution, DTD loading, and network access;
        # `strip_cdata=False` is needed to preserve
        # content within CDATA sections (e.g., for code).        
        parser = etree.XMLParser(
            strip_cdata=False,
            resolve_entities=False,
            load_dtd=False,
            no_network=True,
        )
        root = etree.fromstring(formatted_string.encode("utf-8"), parser=parser)

        def parse_element(element: etree._Element) -> Any:
            # Skip elements starting with underscore
            if element.tag.startswith("_"):
                return {}

            field_info = cls.__fields__.get(element.tag)
            is_verbatim = field_info and field_info.field_info.extra.get(
                "verbatim", False
            )

            if is_verbatim:
                # For code elements, preserve the content as is, including whitespace
                content = element.text if element.text else ""
                # Strip leading and trailing triple backticks if present,
                # accounting for whitespace
                return (
                    content.strip().removeprefix("```").removesuffix("```").strip()
                    if content.strip().startswith("```")
                    and content.strip().endswith("```")
                    else content
                )
            elif len(element) == 0:
                # For non-code leaf elements, strip whitespace
                return element.text.strip() if element.text else ""
            else:
                # For branch elements, handle potential lists or nested structures
                children = [parse_element(child) for child in element]
                if all(child.tag == element[0].tag for child in element):
                    # If all children have the same tag, treat as a list
                    return children
                else:
                    # Otherwise, treat as a dictionary
                    result = {child.tag: parse_element(child) for child in element}
                    # Check if this corresponds to a nested Pydantic model
                    if field_info and issubclass(field_info.type_, BaseModel):
                        return field_info.type_(**result)
                    return result

        result = parse_element(root)
        if not isinstance(result, dict):
            return None
        # Filter out empty dictionaries from skipped underscore fields
        return {k: v for k, v in result.items() if v != {}}

def _ensureSnapshotsFolder(self, subdir=None):
        """ Ensure that the appropriate snapshot folder exists.
        """
        path = ['snapshots', self._snapshot_id]

        if subdir is not None:
            path.extend(subdir.split('/'))

        current = self._tool

        for element in path:

            if element not in current.objectIds():
                # No Unicode IDs!
                current._setObject(str(element), Folder(element))

            current = current._getOb(element)

        return current

def _ensureSnapshotsFolder(self, subdir=None):
        """ Ensure that the appropriate snapshot folder exists.
        """
        path = ['snapshots', self._snapshot_id]

        if subdir is not None:
            path.extend(subdir.split('/'))

        current = self._tool

        for element in path:

            if element not in current.objectIds():
                # No Unicode IDs!
                current._setObject(str(element), Folder(element))
                current = current._getOb(element)
                current.manage_permission(view, ('Manager', 'Owner'), 0)
            else:
                current = current._getOb(element)

        return current

async def execute_sql_for_mcp(
        self, 
        sql: str, 
        limit: int = 1000, 
        timeout: int = 30,
        session_id: str = "mcp_session",
        user_id: str = "mcp_user"
    ) -> Dict[str, Any]:
        """Execute SQL query for MCP interface - unified method"""
        max_retries = 2
        retry_count = 0

        while retry_count <= max_retries:
            try:
                if not sql:
                    return {
                        "success": False,
                        "error": "SQL query is required",
                        "data": None
                    }

                # Import required security modules
                from .security import DorisSecurityManager, AuthContext, SecurityLevel

                # Create proper auth context with read-only permissions
                auth_context = AuthContext(
                    user_id=user_id,
                    roles=["read_only_user"],  # Restrictive role for MCP interface
                    permissions=["read_data"],  # Only read permissions
                    session_id=session_id,
                    security_level=SecurityLevel.INTERNAL
                )

                # Perform SQL security validation if enabled
                if hasattr(self.connection_manager, 'config') and hasattr(self.connection_manager.config, 'security'):
                    if self.connection_manager.config.security.enable_security_check:
                        try:
                            security_manager = DorisSecurityManager(self.connection_manager.config)
                            validation_result = await security_manager.validate_sql_security(sql, auth_context)

                            if not validation_result.is_valid:
                                self.logger.warning(f"SQL security validation failed for query: {sql[:100]}...")
                                return {
                                    "success": False,
                                    "error": f"SQL security validation failed: {validation_result.error_message}",
                                    "error_type": "security_violation",
                                    "blocked_operations": validation_result.blocked_operations,
                                    "risk_level": validation_result.risk_level,
                                    "data": None,
                                    "metadata": {
                                        "query": sql,
                                        "validation_details": {
                                            "blocked_operations": validation_result.blocked_operations,
                                            "risk_level": validation_result.risk_level
                                        }
                                    }
                                }
                            else:
                                self.logger.debug(f"SQL security validation passed for query: {sql[:100]}...")
                        except Exception as security_error:
                            self.logger.error(f"Security validation error: {str(security_error)}")
                            # In case of security validation error, fail safe
                            return {
                                "success": False,
                                "error": f"Security validation system error: {str(security_error)}",
                                "error_type": "security_system_error",
                                "data": None,
                                "metadata": {
                                    "query": sql,
                                    "security_error": str(security_error)
                                }
                            }
                    else:
                        self.logger.info("SQL security check is disabled in configuration")
                else:
                    self.logger.warning("Security configuration not found, proceeding without validation")

                # Add LIMIT if not present and it's a SELECT query
                if sql.upper().startswith("SELECT") and "LIMIT" not in sql.upper():
                    if sql.endswith(";"):
                        sql = sql[:-1]
                    sql = f"{sql} LIMIT {limit}"

                # Create query request
                query_request = QueryRequest(
                    sql=sql,
                    session_id=session_id,
                    user_id=user_id,
                    timeout=timeout,
                    cache_enabled=False  # Disable cache for MCP calls to ensure fresh data
                )

                # Execute query with retry logic
                result = await self.execute_query(query_request, auth_context)

                # Serialize data for JSON response
                serialized_data = []
                for row in result.data:
                    serialized_data.append(self._serialize_row_data(row))

                return {
                    "success": True,
                    "data": serialized_data,
                    "row_count": result.row_count,
                    "execution_time": result.execution_time,
                    "metadata": {
                        "columns": result.metadata.get("columns", []),
                        "query": sql
                    }
                }

            except Exception as e:
                error_msg = str(e)
                error_str = error_msg.lower()

                # Check if it's a connection-related error that we should retry
                connection_errors = [
                    "at_eof", "connection", "closed", "nonetype", 
                    "transport", "reader", "broken pipe", "connection reset"
                ]

                is_connection_error = any(err in error_str for err in connection_errors)

                if is_connection_error and retry_count < max_retries:
                    retry_count += 1
                    self.logger.warning(f"Connection error detected, retrying ({retry_count}/{max_retries}): {e}")

                    # Release the problematic connection
                    try:
                        await self.connection_manager.release_connection(session_id)
                    except Exception:
                        pass  # Ignore cleanup errors

                    # Wait a bit before retry
                    await asyncio.sleep(0.5 * retry_count)
                    continue
                else:
                    # If we've exhausted retries or it's not a connection error, return error
                    error_analysis = self._analyze_error(error_msg)

                    return {
                        "success": False,
                        "error": error_analysis.get("user_message", error_msg),
                        "error_type": error_analysis.get("error_type", "general_error"),
                        "data": None,
                        "metadata": {
                            "query": sql,
                            "error_details": error_msg,
                            "retry_count": retry_count
                        }
                    }

        # This should never be reached, but just in case
        return {
            "success": False,
            "error": "Maximum retries exceeded",
            "data": None,
            "metadata": {
                "query": sql,
                "retry_count": retry_count
            }
        }

