        return True

    for pattern in context.config.ALLOWED_SOURCES:
        if isinstance(  # pylint: disable=isinstance-second-argument-not-valid-type
            pattern, Pattern
        ):
            match = url
        elif looks_like_legacy_allowed_source_regex(pattern):
            warn_legacy_allowed_source_regex(pattern)
            pattern = f"^{pattern}$"
            match = res.hostname
        else:
