        if not RoomID.is_valid(room_id) or not event_id.startswith(EventID.SIGIL):
            raise SynapseError(400, "A valid room ID and event ID must be specified")

        if receipt_type not in self._known_receipt_types:
            raise SynapseError(
                400,
                f"Receipt type must be {', '.join(self._known_receipt_types)}",
            )

        body = parse_json_object_from_request(request)

        # Pull the thread ID, if one exists.
        thread_id = None
        if "thread_id" in body:
            thread_id = body.get("thread_id")
            if not thread_id or not isinstance(thread_id, str):
                raise SynapseError(
                    400,
                    "thread_id field must be a non-empty string",
                    Codes.INVALID_PARAM,
                )

            if receipt_type == ReceiptTypes.FULLY_READ:
                raise SynapseError(
                    400,
                    f"thread_id is not compatible with {ReceiptTypes.FULLY_READ} receipts.",
                    Codes.INVALID_PARAM,
                )

            # Ensure the event ID roughly correlates to the thread ID.
            if not await self._is_event_in_thread(event_id, thread_id):
                raise SynapseError(
                    400,
                    f"event_id {event_id} is not related to thread {thread_id}",
                    Codes.INVALID_PARAM,
                )

        await self.presence_handler.bump_presence_active_time(
            requester.user, requester.device_id
        )

        if receipt_type == ReceiptTypes.FULLY_READ:
            await self.read_marker_handler.received_client_read_marker(
                room_id,
                user_id=requester.user.to_string(),
                event_id=event_id,
            )
        else:
            await self.receipts_handler.received_client_receipt(
                room_id,
                receipt_type,
                user_id=requester.user,
                event_id=event_id,
                thread_id=thread_id,
            )

        return 200, {}

def handler(*args, **kwargs):
        if cherrypy.request.method not in ('GET', 'HEAD'):
            return None
        filename = os.path.join(path, *args)
        assert filename.startswith(path)
        if not os.path.isfile(filename):
            return None
        return serve_file(filename, content_type)

def as_dict_secure(self):
        """Return a sanitised copy of the configuration dict.

        Intended for unauthenticated API access.
        - Blocked sections are omitted entirely.
        - Sensitive keys in remaining sections are replaced by '********'.
        """
        sanitized = {}
        for section, options in self.as_dict().items():
            if section in _SECURE_BLOCKED_SECTIONS:
                continue
            sanitized[section] = {
                key: "********" if _SECURE_SENSITIVE_KEY_RE.search(key) else value for key, value in options.items()
            }
        return sanitized

def as_dict_secure(self):
        """Return a sanitised copy of the configuration dict.

        Intended for unauthenticated API access.
        - Blocked sections are omitted entirely.
        - Sensitive keys in remaining sections are replaced by '********'.
        - Credentials embedded in an URL value are replaced by '********'.
        """
        sanitized = {}
        for section, options in self.as_dict().items():
            if section in _SECURE_BLOCKED_SECTIONS:
                continue
            sanitized[section] = {key: secure_option(key, value) for key, value in options.items()}
        return sanitized

def _sanitize_args(self):
        """Return a sanitized copy of self.args as a dict.

        - password hash is always redacted (even for authenticated users)
        - other sensitive fields are redacted when no authentication is configured
        """
        args_json = vars(self.args).copy()
        if not self.args.password:
            for key in self._SENSITIVE_ARGS:
                if key in args_json:
                    args_json[key] = '********'
        else:
            for key in self._ALWAYS_REDACTED_ARGS:
                if key in args_json and args_json[key]:
                    args_json[key] = '********'
        return args_json

