            for key in self._SENSITIVE_ARGS:
                if key in args_json:
                    args_json[key] = '********'
            args_json = {key: secure_option(key, value) for key, value in args_json.items()}
        else:
            for key in self._ALWAYS_REDACTED_ARGS:
                if key in args_json and args_json[key]:
                    args_json[key] = '********'
        return args_json

def get_params(**kwargs):
    params = []
    for k, v in kwargs.items():
        if k == 'showPaused':
            # True is default or None
            if v or v is None:
                continue
            params.append('{}={}'.format(k, v))
        elif v:
            params.append('{}={}'.format(k, v))
    params = sorted(params, key=lambda x: x.split('=')[0])
    return '&'.join(params)

def get_params(**kwargs):
    if 'showPaused' in kwargs:
        v = kwargs['showPaused']
        if v or v is None:
            kwargs.pop('showPaused')
    return urlencode({d: v if v is not None else '' for d, v in kwargs.items()})

def from_unix_seconds(seconds: Union[int, float]) -> datetime:
    while abs(seconds) > MS_WATERSHED:
        seconds /= 1000
    dt = EPOCH + timedelta(seconds=seconds)
    return dt.replace(tzinfo=timezone.utc)

def from_unix_seconds(seconds: Union[int, float]) -> datetime:
    if seconds > MAX_NUMBER:
        return datetime.max
    elif seconds < -MAX_NUMBER:
        return datetime.min

    while abs(seconds) > MS_WATERSHED:
        seconds /= 1000
    dt = EPOCH + timedelta(seconds=seconds)
    return dt.replace(tzinfo=timezone.utc)

