def pre_social_login(self, request, sociallogin):
        # Link existing accounts with the same email address
        email = sociallogin.account.extra_data.get("email")
        if sociallogin.provider.id == "saml":
            # For SAML, the asserted NameID email cannot be trusted on its own:
            # any tenant can claim any email domain in its SAML configuration. To
            # prevent cross-tenant account takeover (GHSA-h8m9-jgf8-vwvp), only link
            # the incoming SAML session to an existing account when (1) the email
            # domain matches the tenant whose ACS endpoint is being used and (2) the
            # existing user is already a member of that tenant.
            email = sociallogin.user.email
            if not email:
                return

            domain = email.rsplit("@", 1)[-1].lower()
            resolver_match = getattr(request, "resolver_match", None)
            organization_slug = (
                (resolver_match.kwargs or {}).get("organization_slug", "")
                if resolver_match
                else ""
            ).lower()
            # The ACS endpoint is scoped per email domain; reject mismatches so an
            # attacker cannot replay an assertion through another tenant's endpoint.
            if organization_slug != domain:
                return

            try:
                saml_config = SAMLConfiguration.objects.using(MainRouter.admin_db).get(
                    email_domain=domain
                )
            except SAMLConfiguration.DoesNotExist:
                return

            existing_user = self.get_user_by_email(email)
            if existing_user and existing_user.is_member_of_tenant(
                str(saml_config.tenant_id)
            ):
                sociallogin.connect(request, existing_user)
            return

        if email:
            existing_user = self.get_user_by_email(email)
            if existing_user:
                sociallogin.connect(request, existing_user)

def extract_name_from_sld(gs_catalog, sld, sld_file=None):
    try:
        if sld:
            if isfile(sld):
                with open(sld, "rb") as sld_file:
                    sld = sld_file.read()
            if isinstance(sld, str):
                sld = sld.encode('utf-8')
            dom = etree.XML(sld)
        elif sld_file and isfile(sld_file):
            with open(sld_file, "rb") as sld_file:
                sld = sld_file.read()
            if isinstance(sld, str):
                sld = sld.encode('utf-8')
            dom = dlxml.parse(sld)
    except Exception:
        logger.exception("The uploaded SLD file is not valid XML")
        raise Exception(
            "The uploaded SLD file is not valid XML")

    named_dataset = dom.findall(
        "{http://www.opengis.net/sld}NamedLayer")
    user_dataset = dom.findall(
        "{http://www.opengis.net/sld}UserLayer")

    el = None
    if named_dataset and len(named_dataset) > 0:
        user_style = named_dataset[0].findall("{http://www.opengis.net/sld}UserStyle")
        if user_style and len(user_style) > 0:
            el = user_style[0].findall("{http://www.opengis.net/sld}Name")
            if len(el) == 0:
                el = user_style[0].findall("{http://www.opengis.net/se}Name")

        if len(el) == 0:
            el = named_dataset[0].findall("{http://www.opengis.net/sld}Name")
        if len(el) == 0:
            el = named_dataset[0].findall("{http://www.opengis.net/se}Name")

    if not el or len(el) == 0:
        if user_dataset and len(user_dataset) > 0:
            user_style = user_dataset[0].findall("{http://www.opengis.net/sld}UserStyle")
            if user_style and len(user_style) > 0:
                el = user_style[0].findall("{http://www.opengis.net/sld}Name")
                if len(el) == 0:
                    el = user_style[0].findall("{http://www.opengis.net/se}Name")

            if len(el) == 0:
                el = user_dataset[0].findall("{http://www.opengis.net/sld}Name")
            if len(el) == 0:
                el = user_dataset[0].findall("{http://www.opengis.net/se}Name")

    if not el or len(el) == 0:
        if sld_file:
            return splitext(basename(sld_file))[0]
        else:
            raise Exception(
                "Please provide a name, unable to extract one from the SLD.")

    return el[0].text

